import { NativeScriptConfig } from '@nativescript/core';

export default {
  id: 'org.nativescript.nsbenchmark',
  appPath: 'app',
  appResourcesPath: 'App_Resources',
  android: {
    v8Flags: '--expose_gc',
    markingMode: 'none'
  },
  bundler: 'vite',
  bundlerConfigPath: 'vite.config.ts'
} as NativeScriptConfig;---
import { defineConfig } from 'vite';
import { vueConfig } from '@nativescript/vite/vue';;

export default defineConfig(({ mode }) => vueConfig({ mode }));
---
{
  "name": "ns-benchmark",
  "main": "app/app.ts",
  "version": "1.0.0",
  "private": true,
  "dependencies": {
    "@nativescript/core": "9.1.0-alpha.11",
    "@valor/nativescript-websockets": "^2.0.2",
    "nativescript-vue": "^3.0.0"
  },
  "devDependencies": {
    "@nativescript/ios": "9.1.0-alpha.17",
    "@nativescript/tailwind": "^4.0.0",
    "@nativescript/types": "~9.0.0",
    "@nativescript/vite": "8.0.0-alpha.69",
    "@nativescript/webpack": "~5.0.31",
    "@types/node": "^20.0.0",
    "@vitejs/plugin-vue": "^6.0.8",
    "@vitejs/plugin-vue-jsx": "^5.1.6",
    "nativescript": "9.1.0-alpha.15",
    "tailwindcss": "^4.0.0",
    "typescript": "~6.0.0",
    "vue-tsc": "^3.3.8"
  },
  "scripts": {
    "android": "ns debug android",
    "ios": "ns debug ios"
  }
}

